import{_ as o}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as e,af as i}from"./chunks/mermaid.YsAH9es0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Agent 交付闭环：把补丁与迁移类任务做成可编排、可验证的流程","description":"从阿里云《AI Agent Handbook》PatchPilot 案例提炼 5 张可照做的实践卡——失败任务分流、State-First 依赖分析、结构化失败记忆、质量门禁、端到端交付度量，每张都配前置条件、适用边界、失败模式和可验证指标，并给出小团队降级版。","frontmatter":{"title":"Agent 交付闭环：把补丁与迁移类任务做成可编排、可验证的流程","description":"从阿里云《AI Agent Handbook》PatchPilot 案例提炼 5 张可照做的实践卡——失败任务分流、State-First 依赖分析、结构化失败记忆、质量门禁、端到端交付度量，每张都配前置条件、适用边界、失败模式和可验证指标，并给出小团队降级版。","domain":"practice","tags":["agent-workflow","code-migration","quality-gate"],"navOrder":30,"prev":{"text":"采购与实施方案","link":"/zh/practice/procurement-plan"},"next":false},"headers":[],"relativePath":"zh/practice/agent-handbook/case-patch-delivery.md","filePath":"zh/practice/agent-handbook/case-patch-delivery.md","lastUpdated":1792458633000}'),d={name:"zh/practice/agent-handbook/case-patch-delivery.md"};function l(a,t,n,s,g,c){return e(),r("div",null,[...t[0]||(t[0]=[i(`<h1 id="agent-交付闭环-把补丁与迁移类任务做成可编排、可验证的流程" tabindex="-1">Agent 交付闭环：把补丁与迁移类任务做成可编排、可验证的流程 <a class="header-anchor" href="#agent-交付闭环-把补丁与迁移类任务做成可编排、可验证的流程" aria-label="Permalink to &quot;Agent 交付闭环：把补丁与迁移类任务做成可编排、可验证的流程&quot;">​</a></h1><blockquote><p>来源：阿里云《AI Agent Handbook》第 25 章 研发效能 · <a href="https://github.com/aliyun/ai-agent-handbook/blob/main/06-case-study/%E7%AC%AC25%E7%AB%A0%20%E7%A0%94%E5%8F%91%E6%95%88%E8%83%BD/PatchPilot%20Agents%EF%BC%9A%E8%AE%A9%E5%86%85%E6%A0%B8%E8%A1%A5%E4%B8%81%E4%BA%A4%E4%BB%98%E6%88%90%E4%B8%BA%E5%8F%AF%E7%BC%96%E6%8E%92%E3%80%81%E5%8F%AF%E9%AA%8C%E8%AF%81%E7%9A%84%E5%B7%A5%E7%A8%8B%E9%97%AD%E7%8E%AF.md" target="_blank" rel="noreferrer">PatchPilot Agents：让内核补丁交付成为可编排、可验证的工程闭环</a>（原文 markdown：<a href="https://raw.githubusercontent.com/aliyun/ai-agent-handbook/HEAD/06-case-study/%E7%AC%AC25%E7%AB%A0%20%E7%A0%94%E5%8F%91%E6%95%88%E8%83%BD/PatchPilot%20Agents%EF%BC%9A%E8%AE%A9%E5%86%85%E6%A0%B8%E8%A1%A5%E4%B8%81%E4%BA%A4%E4%BB%98%E6%88%90%E4%B8%BA%E5%8F%AF%E7%BC%96%E6%8E%92%E3%80%81%E5%8F%AF%E9%AA%8C%E8%AF%81%E7%9A%84%E5%B7%A5%E7%A8%8B%E9%97%AD%E7%8E%AF.md" target="_blank" rel="noreferrer">raw</a>）。本文只做转述与提炼，不搬运原文。</p><p>定位：这是<a href="/zh/practice/">企业实践</a>里的「怎么落地」一篇。<a href="/zh/practice/reporter.html">Vibe Coding 报告</a> 管「发生了什么」，<a href="/zh/practice/procurement-plan.html">采购与实施方案</a> 管「买什么」，本页管「买了之后怎么把 Agent 编排进交付流程」。</p></blockquote><h2 id="_0-三十秒判断-值不值得抄" tabindex="-1">0. 三十秒判断：值不值得抄 <a class="header-anchor" href="#_0-三十秒判断-值不值得抄" aria-label="Permalink to &quot;0. 三十秒判断：值不值得抄&quot;">​</a></h2><p>原文把难点说得很准：&quot;难点不在于“能不能生成一段修改”，而在于：<strong>能否让一次补丁交付具备可追踪的过程、可验证的结果和可持续优化的机制。</strong>&quot;</p><p>这篇真正可以照做的只有一件事：<strong>别让 Agent 直接吐补丁，先给它一个「状态 → 判断 → 执行 → 门禁 → 回检」的流水线。</strong> 下面 5 张卡就是这条流水线拆开的，每张都能单独上。</p><p>两个必须先说清楚的前提：</p><ol><li><strong>原文正文的「阶段性实践效果」一节里没有任何数字</strong>，只有一张配图。所以这篇不能当作「AI 能提效多少」的通用依据，只能当工程结构参考。</li><li><strong>场景高度特化</strong>：内核补丁交付（上游 patch 回合到下游分支）。原文自己给了外推边界——&quot;这套方法同样适用于 SDK 大版本升级、跨分支移植、fork 同步等代码迁移场景。&quot;也就是说你手上得有一类「重复、证据充分、结果可验证」的迁移任务，纯新功能开发不在适用范围内。</li></ol><hr><h2 id="卡-1-失败任务自动分流-快筛-精判" tabindex="-1">卡 1｜失败任务自动分流：快筛 + 精判 <a class="header-anchor" href="#卡-1-失败任务自动分流-快筛-精判" aria-label="Permalink to &quot;卡 1｜失败任务自动分流：快筛 + 精判&quot;">​</a></h2><p><strong>要解决的问题</strong> &quot;一次合入失败可能是依赖缺失、上下文变化或真实代码冲突。人工先判断“值不值得修、能不能修”，本身就消耗大量时间。&quot;——大量同构失败任务下，「判断本身」比「修复本身」更费人。</p><p><strong>具体做法</strong></p><table tabindex="0"><thead><tr><th>步骤</th><th>动作</th><th>关键设计</th></tr></thead><tbody><tr><td>1. 规则层打分</td><td>用启发式规则评估四个维度：冲突规模、缺失符号、危险变更、补丁复杂度</td><td>规则先筛，成本≈0</td></tr><tr><td>2. 分三档</td><td>明确可修 / 模糊区间 / 高风险</td><td>阈值来自回放历史失败样本，不是拍脑袋</td></tr><tr><td>3. 模糊区间才进 LLM</td><td>&quot;仅将处于模糊区间的任务交由 LLM 进一步判断&quot;</td><td>原文：&quot;先以启发式规则快速评估，再仅对模糊任务调用 LLM 精判&quot;</td></tr><tr><td>4. 强制升级出口</td><td>高风险改动直接转人工，Agent 不再往下走</td><td>原文：&quot;自动化不是无边界自治。&quot;</td></tr><tr><td>5. 落库分流理由</td><td>记录判定依据，供后续调阈值</td><td>分流本身也是可优化对象</td></tr></tbody></table><p>&quot;这样形成“快筛 + 精判”的双层漏斗：明确任务快速推进，复杂任务再投入深度分析。&quot;</p><p><strong>前置条件</strong></p><ul><li>有机器可读的合入日志（<code>git apply</code> / <code>rebase</code> / <code>merge</code> 的原始输出），不能只有一句「合并失败」。</li><li>有历史失败样本能用来回放定阈值。</li><li>有一条明确的人工升级通道（有归属人、有 SLA），否则「升级」= 丢任务。</li></ul><p><strong>适用边界</strong></p><ul><li>任务量大、同构、输入明确（原文方法论第一条：&quot;优先选择日志、代码、任务状态等输入明确的场景，而不是一开始追求全自动决策。&quot;）。</li><li>不适合：一次性新功能、探索性重构、低频长尾任务——这些直接人工做更快。</li></ul><p><strong>反例 / 失败模式</strong></p><ul><li>阈值靠感觉定 → 危险改动被塞进自动通道，出事才知道。</li><li>只做规则不留升级出口 → 规则失效时任务静默卡住。</li><li>LLM 判定结果不落库 → 无法复盘，阈值永远调不准。</li></ul><p><strong>可验证效果指标</strong></p><ul><li>自动处理占比、人工升级率、<strong>误升级率</strong>（升级后人工发现本可自动的比例）。</li><li>单任务的前置判断耗时（规则层应≈0）。</li></ul><p><strong>原文</strong> &quot;PatchPilot 先以启发式规则快速评估冲突规模、缺失符号、危险变更和补丁复杂度；仅将处于模糊区间的任务交由 LLM 进一步判断。&quot; &quot;证据充分且风险可控的任务自动处理；不确定或高风险任务升级工程师&quot;</p><hr><h2 id="卡-2-state-first-依赖分析-别只找缺失符号" tabindex="-1">卡 2｜State-First 依赖分析：别只找缺失符号 <a class="header-anchor" href="#卡-2-state-first-依赖分析-别只找缺失符号" aria-label="Permalink to &quot;卡 2｜State-First 依赖分析：别只找缺失符号&quot;">​</a></h2><p><strong>要解决的问题</strong> 上游补丁回合失败，表面是冲突，真实原因常常是「这段代码已经不是你记忆里的样子」：&quot;失败原因往往不是单一的 Git 冲突：同一函数可能已被重构，结构体字段或函数签名可能已演化，修复所依赖的前置提交也可能尚未进入目标分支。&quot;</p><p><strong>具体做法</strong></p><ol><li><strong>意图分析先收窄范围</strong>：补丁想干什么，决定看哪几个文件/函数，而不是全仓扫。</li><li><strong>以「状态偏离」为线索</strong>，而不是以「缺失符号」为线索：函数实现、结构体字段、函数签名三类演化都要进判断。原文：&quot;仅找缺失符号会遗漏代码演化造成的真实冲突&quot;、&quot;以“代码状态偏离”而非单纯缺失符号为线索追踪依赖：函数实现、结构体字段和函数签名的演化都会纳入判断。&quot;</li><li><strong>依赖只从 Git 事实里选</strong>：先用 Git 命令枚举候选 commit（<code>git log -S</code> / <code>git log --oneline &lt;tag&gt;..&lt;branch&gt;</code> / <code>git show</code>），模型只做选择，不做编造。原文：&quot;要求通过 Git 命令枚举 commit SHA，以工具输出作为事实依据&quot;。</li><li><strong>递归但有上限</strong>：定位必要前置提交要递归，递归深度/时间窗要设上限，否则会一路拉到不相关提交。原文给的反面是&quot;避免只按缺失符号补丁、导致依赖链膨胀&quot;。</li></ol><p><strong>前置条件</strong></p><ul><li>仓库有完整历史（没被 squash / 单次导入过）。</li><li>符号级搜索与 <code>git log -S</code> 可用。</li><li>能定义「什么算同一个符号的重构」——这是脏活，先人工标一批样本。</li></ul><p><strong>适用边界</strong></p><ul><li>适用：patch 回合、fork 同步、跨分支移植、大版本升级。</li><li>不适用：无历史的仓库、只有二进制产物的仓库、单文件微调。</li><li>大仓先做范围收窄，否则状态偏离本身就会超时。</li></ul><p><strong>反例 / 失败模式</strong></p><ul><li>直接问模型「需要哪个前置提交」→ 它会编一个看起来很像的 SHA。原文点名了这个坑：&quot;依赖提交必须由 Git 工具精确枚举，避免模型凭直觉补全不存在的前置变更。&quot;</li><li>只做符号级搜索、不看签名/字段演化 → 补丁能编译但行为变了。</li><li>递归无上限 → 依赖链膨胀，合出来的 diff 大到没人敢 review。</li></ul><p><strong>可验证效果指标</strong></p><ul><li>引入的无关提交数 / 有效依赖提交数（比值越低越好）。</li><li>首轮解冲突成功率、平均重试轮次。</li><li>单个补丁最终 diff 行数中「非必要变更」占比。</li></ul><p><strong>原文</strong> &quot;结合补丁意图、代码状态和前置提交，递归识别必要依赖&quot; &quot;比较函数、结构体和签名的状态偏离，再定位必要前置提交&quot;</p><hr><h2 id="卡-3-结构化失败记忆-让-agent-不要重复走死路" tabindex="-1">卡 3｜结构化失败记忆：让 Agent 不要重复走死路 <a class="header-anchor" href="#卡-3-结构化失败记忆-让-agent-不要重复走死路" aria-label="Permalink to &quot;卡 3｜结构化失败记忆：让 Agent 不要重复走死路&quot;">​</a></h2><p><strong>要解决的问题</strong> 多 Agent / 多轮重试最容易浪费的地方：第二轮干了和第一轮一样的事。原文给的原因——多轮尝试容易重复走进同一条死路。</p><p><strong>具体做法</strong></p><ol><li><strong>每轮落一条结构化记录</strong>（不是自由文本日志），固定三字段：<code>处理方案</code> / <code>失败原因</code> / <code>改动范围</code>。</li><li><strong>重试前强制读这份记忆</strong>，并且要求本轮方案与记忆中的方案有差异，否则不允许提交。</li><li><strong>先对齐补丁意图再动手</strong>：原文&quot;解决 Git 冲突不等于保留了原补丁意图。AI 可能产生残留冲突标记、遗漏关键改动，甚至生成上游不存在的代码。&quot;——解冲突前先复述「原补丁想做什么」。</li><li><strong>改动范围只记摘要 + 文件列表</strong>，不要贴全量 diff，否则记忆本身会撑爆上下文。</li></ol><p><strong>前置条件</strong></p><ul><li>任务状态可持久化（不能只活在一次会话里）。</li><li>有一个固定的记忆文件/表，按 task_id 归档。</li><li>迭代过程本身能被脚本包裹（否则「每轮都记」靠自觉必然漏）。</li></ul><p><strong>适用边界</strong></p><ul><li>适用：需要 ≥2 轮重试的任务（真·复杂回合）。</li><li>不适合：一次就过的任务，写记忆是纯开销。</li><li>记忆需要定期清理/归档，否则检索不到有效历史。</li></ul><p><strong>反例 / 失败模式</strong></p><ul><li>记忆写成自然语言流水账 → 检索不到「已经试过什么」。</li><li>重试不读记忆 → 原地打转，且看起来在「努力」。</li><li><code>改动范围</code> 记全量 diff → token 成本失控。</li><li>只记失败不记成功方案 → 丢掉可复用路径。</li></ul><p><strong>可验证效果指标</strong></p><ul><li>平均重试轮次、<strong>重复失败率</strong>（相同失败原因重复出现的比例）。</li><li>单轮 token / 调用成本。</li><li>记忆命中后本轮方案变化率（应≈100%）。</li></ul><p><strong>原文</strong> &quot;Agent 的每一轮尝试都会记录处理方案、失败原因和改动范围；后续重试带着这些结构化记忆继续，而不是重复同一条无效路径。&quot; &quot;保存方案、失败原因和改动范围，驱动下一轮差异化尝试&quot;</p><hr><h2 id="卡-4-质量门禁三件套-能合入-可交付" tabindex="-1">卡 4｜质量门禁三件套：能合入 ≠ 可交付 <a class="header-anchor" href="#卡-4-质量门禁三件套-能合入-可交付" aria-label="Permalink to &quot;卡 4｜质量门禁三件套：能合入 ≠ 可交付&quot;">​</a></h2><p><strong>要解决的问题</strong> 回合成功、PR 成功之后仍然可能交付失败。&quot;一次回合成功后，仍可能在 PR、检测轮次或后续链路中失败。只统计“命令执行成功”会高估自动化价值。&quot;</p><p><strong>具体做法</strong></p><p>按顺序跑三层检查，每层都有可机器判定的输出：</p><table tabindex="0"><thead><tr><th>层</th><th>检查什么</th><th>最小实现</th></tr></thead><tbody><tr><td>L1 冲突残留</td><td>残留冲突标记、空白/行尾破损</td><td><code>grep -n &#39;&lt;&lt;&lt;&lt;&lt;&lt;&lt;|=======|&gt;&gt;&gt;&gt;&gt;&gt;&gt;&#39;</code> + <code>git diff --check</code></td></tr><tr><td>L2 代码漂移</td><td>生成物偏离基线或上游意图</td><td>与基线 branch 的 diff 审查 / 结构化 diff 统计</td></tr><tr><td>L3 语义偏差</td><td>行为不等价（最贵，放在最后）</td><td>编译 + 现有测试；没有测试就人工抽检</td></tr></tbody></table><ul><li>原文：&quot;执行后依次检查冲突残留、代码漂移与语义偏差。&quot;</li><li>每层都要定义<strong>不通过时的去向</strong>（重试 / 转人工），这就是原文说的门禁：&quot;对每个自动化动作定义可验证的结果与人工升级条件。&quot;</li><li>门禁不过不许静默通过。原文：&quot;不把“能合入”误判为“可交付”&quot;</li></ul><p><strong>前置条件</strong></p><ul><li>CI 能编译、能跑测试（哪怕只有 smoke test）。</li><li>有一条基线可比对（目标分支 / 上游 tag）。</li><li>门禁规则与升级条件写进仓库，而不是记在某个人的脑子里。</li></ul><p><strong>适用边界</strong></p><ul><li>三层里 L1、L2 可以完全自动化；L3 在没有测试的仓库里只能降级为人工抽检——这时候不要假装自动。</li><li>门禁不是越多越好，超过 ~5 条以后没人愿意看。</li></ul><p><strong>反例 / 失败模式</strong></p><ul><li>只检查命令返回码 → 这正是原文反对的。</li><li>门禁不过但不升级 → 静默通过，问题一路漏到线上。</li><li>阈值调到「刚好能过」→ 门禁形式化，指标好看但缺陷没少。</li><li>把语义偏差交给模型自查 → 自己批自己的卷子。</li></ul><p><strong>可验证效果指标</strong></p><ul><li>门禁拦截率（拦下 / 提交总次数）。</li><li>拦截后的人工返工率（拦截是否真拦住了问题，还是噪音）。</li><li>逃逸到 PR / 上线后的缺陷率。</li></ul><p><strong>原文</strong> &quot;检查残留冲突标记、代码漂移和语义偏差&quot; &quot;每一个自动化结论都能对应到任务状态、Git 事实或质量检查结果。&quot;</p><hr><h2 id="卡-5-以端到端交付定义成功-持久化任务状态" tabindex="-1">卡 5｜以端到端交付定义成功 + 持久化任务状态 <a class="header-anchor" href="#卡-5-以端到端交付定义成功-持久化任务状态" aria-label="Permalink to &quot;卡 5｜以端到端交付定义成功 + 持久化任务状态&quot;">​</a></h2><p><strong>要解决的问题</strong> 两个坑：一是只统计「命令执行成功」，二是任务在异常中断后无声消失。第二种更贵，因为它不可见。</p><p><strong>具体做法</strong></p><ol><li><strong>建一条任务状态链</strong>：入队 → 分析 → 执行 → 检测轮次 → PR → 合入。原文：&quot;任务从入队到 PR 合入的状态被连续记录&quot;。</li><li><strong>回合成功后不结束，进入回检</strong>：自动创建检测轮次、回检 PR 与交付状态。原文：&quot;回合成功后自动创建检测轮次、回检 PR 与交付状态，并将任务、日志、审查结论和最终产物统一关联。&quot;</li><li><strong>持久化状态负责恢复与重排</strong>：中断、超时、异常时基于持久化状态恢复或重新调度，&quot;而不是把任务留在不可见的中间状态&quot;。</li><li><strong>运行保障三件套</strong>：去重、调度恢复、超时处置。原文：&quot;PatchPilot 将任务状态、执行产物和审查结果持续沉淀；通过去重、调度恢复和超时处置，避免重复执行、异常中断或任务遗漏影响整体交付节奏。&quot;</li><li><strong>换掉 KPI</strong>：原文：&quot;PatchPilot 以“是否完成交付”而非“是否完成一次执行”衡量效果。&quot;</li></ol><p><strong>前置条件</strong></p><ul><li>有可查询的任务存储（Issue / PR / 一张表都行）。</li><li>有明确的超时阈值和恢复入口（谁来捞、什么时候捞）。</li><li>任务有唯一 ID，产物、日志、审查结论都挂在 ID 上。</li></ul><p><strong>适用边界</strong></p><ul><li>适用：每周几十个以上重复任务、多人/多 worker 并行。</li><li>不适合：一天跑不到 10 个任务时，一张表就够了，别上调度器。</li><li>多 worker 并行时，去重不是优化项而是必需项。</li></ul><p><strong>反例 / 失败模式</strong></p><ul><li>用「一次执行成功率」当团队 KPI → 报表漂亮，交付周期没变。</li><li>中断后不恢复也不告警 → 任务烂在队列里，没人知道。</li><li>同一补丁被两个 worker 同时处理 → 冲突加倍。</li><li>状态写在会话上下文里 → 进程一重启全丢。</li></ul><p><strong>可验证效果指标</strong></p><ul><li>端到端交付率（入队 → 合入）。</li><li>任务吞吐（每周完成数）、失败可见性（卡住任务的平均滞留时长）。</li><li>超时 / 丢失任务数、返工率。</li><li>原文给的完整观察清单：&quot;同时观察效率、成本、交付率、人工升级率和返工率，避免只看单点成功率。&quot;</li></ul><p><strong>原文</strong> &quot;调度侧以持久化任务状态管理执行与恢复，使异常中断不会让任务悄然丢失。&quot; &quot;系统的优化对象不仅是“单次解冲突是否成功”，还包括任务吞吐、失败可见性和交付链路的稳定性。&quot;</p><hr><h2 id="_3-哪些是阿里云的主张-哪些是你能自己复现的" tabindex="-1">3. 哪些是阿里云的主张，哪些是你能自己复现的 <a class="header-anchor" href="#_3-哪些是阿里云的主张-哪些是你能自己复现的" aria-label="Permalink to &quot;3. 哪些是阿里云的主张，哪些是你能自己复现的&quot;">​</a></h2><table tabindex="0"><thead><tr><th>条目</th><th>性质</th><th>说明</th></tr></thead><tbody><tr><td>多阶段工作流 + 每阶段明确输入/产出/状态</td><td><strong>主张</strong>（设计取向）</td><td>无平台依赖，任何仓库都能搭</td></tr><tr><td>快筛 + 精判双层漏斗</td><td><strong>主张 + 可复现</strong></td><td>规则层几十行代码即可</td></tr><tr><td>State-First 依赖分析</td><td><strong>可复现</strong></td><td>全靠 Git 原生命令</td></tr><tr><td>工具约束推理（枚举 commit SHA）</td><td><strong>可复现</strong></td><td>Agent 强制走工具调用即可</td></tr><tr><td>结构化失败记忆</td><td><strong>可复现</strong></td><td>一个文件或一张表</td></tr><tr><td>质量门禁三件套</td><td><strong>可复现</strong></td><td>grep + diff + CI</td></tr><tr><td>持久化任务状态 / 恢复 / 去重 / 超时</td><td><strong>可复现，但需要最小任务系统</strong></td><td>一个人做要先砍到只剩状态表</td></tr><tr><td>价值来自「轻量规则 + 昂贵推理 + 质量校验 + 调度回检」四层组合</td><td><strong>主张（无对照实验）</strong></td><td>原文没给分层消融数据，不能当成因果结论</td></tr><tr><td>第 4 节的效果数字</td><td><strong>内部数据</strong></td><td>见下节，只有配图、无口径定义</td></tr></tbody></table><p>原文自己的排序也值得抄：&quot;先建立工作流，再引入 Agent。&quot;——理由是&quot;没有状态、上下文和回检的 Agent，难以在生产工程中稳定运行。&quot;</p><h2 id="_4-内部数据-配图口径-务必带-caveat-使用" tabindex="-1">4. 内部数据（配图口径，务必带 caveat 使用） <a class="header-anchor" href="#_4-内部数据-配图口径-务必带-caveat-使用" aria-label="Permalink to &quot;4. 内部数据（配图口径，务必带 caveat 使用）&quot;">​</a></h2><p>原文正文的「4. 阶段性实践效果」一节<strong>只有一张图</strong>，数字全部来自该图（<code>assets/imgs/chapter-25/image-008.svg</code>，截至 2026.09.15，标注覆盖 Linux 5.10、6.6 等多个内核版本）：</p><table tabindex="0"><thead><tr><th>口径</th><th>图中数值</th></tr></thead><tbody><tr><td>版本覆盖</td><td>10 个版本任务</td></tr><tr><td>处理规模</td><td>10,000+ 累计处理补丁，支撑数千个 CVE 修复</td></tr><tr><td>AI 解冲突成功任务</td><td>1,200</td></tr><tr><td>已合入 PR</td><td>4,983</td></tr><tr><td>单个版本交付周期</td><td>约 2 个月 → 1–2 周</td></tr></tbody></table><p>图来源：<a href="https://github.com/aliyun/ai-agent-handbook/blob/main/assets/imgs/chapter-25/image-008.svg" target="_blank" rel="noreferrer">image-008.svg</a></p><p><strong>读法</strong>：当量级参考，不要当 KPI 承诺。原文没有给出对照组、没有定义「AI 解冲突成功」的判定标准、没有说明 1,200 与 4,983 的关系、也没给统计时间窗。这些数字无法被独立复现，也无法外推到你的仓库。</p><h2 id="_5-一人公司-小团队降级版" tabindex="-1">5. 一人公司 / 小团队降级版 <a class="header-anchor" href="#_5-一人公司-小团队降级版" aria-label="Permalink to &quot;5. 一人公司 / 小团队降级版&quot;">​</a></h2><p>原文整套东西假设了「多内核版本 + 大批量补丁」。一个人手上通常只有几十个任务，照抄会过度工程。降级原则：<strong>保留状态与门禁，砍掉调度与自动分流。</strong></p><table tabindex="0"><thead><tr><th>卡</th><th>小团队做法</th><th>最小工具</th><th>明确放弃</th></tr></thead><tbody><tr><td>卡 1 分流</td><td>5 条 checklist 人工打分（冲突行数 / 触及公共 API / 改签名或结构体 / 跨版本 / 补丁规模），只有灰区才问一次 LLM；结果写进 issue 标签</td><td>Issue 标签 + 一个固定 prompt</td><td>自动分流、阈值自学习</td></tr><tr><td>卡 2 依赖分析</td><td>手工导一份「状态偏离清单」（<code>git log -S&#39;&lt;符号&gt;&#39;</code> + <code>git diff &lt;tag&gt;..&lt;branch&gt;</code> 关键文件），让 Agent 只从清单里选前置提交</td><td>一个 JSON 清单文件</td><td>递归自动定位</td></tr><tr><td>卡 3 失败记忆</td><td>仓库内 <code>.agents/failure-log.md</code>，每轮追加 <code>方案 / 失败原因 / 改动范围</code> 三行；重试前先读</td><td>一个 Markdown 文件</td><td>自动检索、记忆清理</td></tr><tr><td>卡 4 质量门禁</td><td>冲突标记 grep + <code>git diff --check</code> + 跑一次测试；语义偏差 100% 人工过</td><td>三条命令 + 现有 CI</td><td>自动语义审查</td></tr><tr><td>卡 5 端到端度量</td><td>一张状态表（queued / in-progress / blocked / merged），卡住 &gt;24h 手动提醒；只留 4 个指标：交付率、人工升级率、返工率、单任务耗时</td><td>一张表格 + 定时提醒</td><td>自动恢复、自动重排、去重服务</td></tr></tbody></table><p><strong>一人公司推荐顺序</strong>（先做能被验证的，最后做最贵的）：</p><ol><li>第 1 周：状态表 + 回检（卡 5 的最小版）——先让你能看见任务。</li><li>第 2 周：质量门禁（卡 4 的 L1/L2）——最便宜、收益最直接。</li><li>第 3 周：失败记忆（卡 3）——重试次数一多就回本。</li><li>之后：依赖分析（卡 2）、分流（卡 1）——只有任务量真的上来了才值得。</li></ol><p>配套一句原文，正好是上面顺序的理由：&quot;从高频、证据充分的问题开始。&quot;（原文方法论第一条；同条正文为&quot;优先选择日志、代码、任务状态等输入明确的场景，而不是一开始追求全自动决策。&quot;）</p><h2 id="_6-与现有页面的重叠与插入位置" tabindex="-1">6. 与现有页面的重叠与插入位置 <a class="header-anchor" href="#_6-与现有页面的重叠与插入位置" aria-label="Permalink to &quot;6. 与现有页面的重叠与插入位置&quot;">​</a></h2><p><strong>新页位置</strong>：<code>docs/zh/practice/agent-delivery-loop.md</code>（frontmatter 已按仓库惯例写好 <code>navOrder: 30</code>、<code>prev: 采购与实施方案</code>、<code>next: false</code>）。</p><p><strong>index.md 插入点</strong>：<a href="https://github.com/zenHeart/learn-ai/blob/master/docs/zh/practice/index.md" target="_blank" rel="noreferrer"><code>docs/zh/practice/index.md</code></a> 的「按决策顺序读」目前只有两级——1. 先看形势（reporter）、2. 再决定怎么买（procurement-plan）。本页应作为 <strong>3. 再决定怎么落地</strong> 插在采购之后：</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### 3. 再落地</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Agent 交付闭环</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">/zh/practice/agent-delivery-loop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) — 有了一堆工具之后，怎么把它们编排成「状态 → 判断 → 执行 → 门禁 → 回检」。内核补丁回合案例，含一人公司降级版。</span></span></code></pre></div><p>顺序理由：采购页回答「买什么」，本页回答「买了之后怎么编排出可验证的结果」，是同一条决策链的下一步，不应该插在 reporter 之前。</p><p><strong>重叠与分工</strong></p><table tabindex="0"><thead><tr><th>现有页面</th><th>重叠点</th><th>建议</th></tr></thead><tbody><tr><td><code>docs/practice/ai-efficiency-practice.md</code>（AI 提效实践：跨平台齐淼树重构）</td><td>它的第 3 条「每个 AI 输出环节设置人工审核点，AI 提效但不放任」与卡 1 的升级出口、卡 4 的门禁是同一件事；它给的「整体研发效率提升 40%+」是厂商侧口径</td><td><strong>不复制内容</strong>。英文页只在「核心要点」第 3 条后加一行交叉链接指向本页；本页在卡 4 末尾注明它是那页第 3 条的流程化细则。两者数字口径不同，不要互相引用数据</td></tr><tr><td><code>docs/zh/practice/procurement-plan.md</code></td><td>都涉及「怎么落地 AI」，但那页管预算/合规/模型搭配</td><td>不改内容，本页 frontmatter 用 <code>prev</code> 链过去即可；正文开头已声明边界</td></tr><tr><td><code>docs/zh/practice/reporter.md</code></td><td>都会提到「AI 提效」</td><td>不引它的行业数据，本页只讲单案例机制</td></tr><tr><td><code>docs/practice/ai-landing-discussion.md</code></td><td>它第 3 条写的是「AI 适合『草稿 + 人工审核』模式」，与卡 1 的升级出口、卡 4 的门禁同一件事；它第 1 条「场景选择 &gt; 技术选型」与卡 1「从高频、证据充分的问题开始」也重复</td><td>两页都只留观点，机制细则统一放本页。建议在 landing 页那一条后加一行「工程机制细则见 /zh/practice/agent-delivery-loop」</td></tr></tbody></table><p><strong>英文站</strong>：<code>docs/practice/index.md</code> 目前列 Hiring / Landing discussion / Team efficiency 三条。若本页同步出英文版，放在 Team efficiency 之后、作为机制细则页；不同步也可以，因为本页 frontmatter 已把内容锚定在中文决策链上。</p><h2 id="_7-一句话记忆" tabindex="-1">7. 一句话记忆 <a class="header-anchor" href="#_7-一句话记忆" aria-label="Permalink to &quot;7. 一句话记忆&quot;">​</a></h2><blockquote><p>让模型少写点代码，多写点状态。原文：&quot;PatchPilot 的技术重点不在于让模型“多写代码”，而在于把模型能力约束在可验证的工程边界中。&quot;——边界由三样东西撑起来：&quot;它通过意图分析缩小关注范围，通过 Git 工具提供可追溯事实，通过工作流状态机串联分析、执行与回检。&quot;</p></blockquote>`,105)])])}const A=o(d,[["render",l]]);export{b as __pageData,A as default};
